import { Fragment } from "react";
import Link from "next/link";
import type { LeadStatus as LS, LeadType } from "@prisma/client";
import { Download, MessageCircle } from "lucide-react";
import { db } from "@/lib/db";
import { cn, formatDate } from "@/lib/utils";
import { PageHeader } from "@/components/admin/ui";
import { LeadStatus } from "@/components/admin/SmallForms";

const TYPES: Record<LeadType, string> = { B2B_QUOTE: "B2B quote", ENGRAVING: "Engraving", CONTACT: "Contact" };

export default async function AdminLeads({ searchParams }: PageProps<"/admin/leads">) {
  const sp = await searchParams;
  const type = typeof sp.type === "string" && sp.type in TYPES ? (sp.type as LeadType) : undefined;
  const status = typeof sp.status === "string" && ["NEW", "CONTACTED", "QUOTED", "WON", "LOST"].includes(sp.status) ? (sp.status as LS) : undefined;
  const leads = await db.lead.findMany({ where: { ...(type ? { type } : {}), ...(status ? { status } : {}) }, orderBy: { createdAt: "desc" }, take: 300 });
  const link = (t?: string) => `/admin/leads${t ? `?type=${t}` : ""}`;

  return (
    <>
      <PageHeader title="Leads & quote requests" description="B2B quotes, engraving requests and contact-form enquiries." actions={<a href="/api/admin/export?type=leads" className="btn-outline"><Download className="h-4 w-4" /> Export CSV</a>} />
      <div className="mb-4 flex flex-wrap gap-1 text-sm">
        <Link href={link()} className={cn("rounded-full px-3 py-1.5", !type ? "bg-ink text-white" : "bg-white")}>All</Link>
        {(Object.keys(TYPES) as LeadType[]).map((t) => <Link key={t} href={link(t)} className={cn("rounded-full px-3 py-1.5", type === t ? "bg-ink text-white" : "bg-white")}>{TYPES[t]}</Link>)}
      </div>
      <div className="grid gap-4 lg:grid-cols-2">
        {leads.map((l) => {
          const details = l.details as Record<string, string>;
          const phone = l.phone.replace(/\D/g, "").replace(/^(\d{10})$/, "91$1");
          return (
            <article key={l.id} className={cn("rounded-lg border bg-white p-4", l.status === "NEW" ? "border-brass" : "border-line")}>
              <div className="flex items-start justify-between gap-3">
                <div>
                  <span className="badge bg-paper text-ink-soft">{TYPES[l.type]}</span>
                  <p className="mt-1 font-semibold">{l.name}{l.company && <span className="font-normal text-muted"> · {l.company}</span>}</p>
                  <p className="text-xs text-muted">{formatDate(l.createdAt, true)}{l.city && ` · ${l.city}`}</p>
                </div>
                <div className="w-36 shrink-0"><LeadStatus id={l.id} status={l.status} note={l.adminNote ?? ""} /></div>
              </div>
              {l.message && <p className="mt-3 whitespace-pre-line text-sm">{l.message}</p>}
              {Object.keys(details).length > 0 && (
                <dl className="mt-3 grid grid-cols-[auto_1fr] gap-x-3 gap-y-1 rounded bg-paper p-3 text-xs">
                  {Object.entries(details).map(([k, v]) => <Fragment key={k}><dt className="font-semibold capitalize">{k}</dt><dd>{v}</dd></Fragment>)}
                </dl>
              )}
              <div className="mt-3 flex flex-wrap gap-2 text-sm">
                <a href={`tel:+${phone}`} className="btn-outline py-1.5">Call {l.phone}</a>
                <a href={`https://wa.me/${phone}?text=${encodeURIComponent(`Hello ${l.name}, this is Sun Metals Store regarding your enquiry.`)}`} target="_blank" rel="noopener noreferrer" className="btn-outline py-1.5"><MessageCircle className="h-4 w-4" /> WhatsApp</a>
                {l.email && <a href={`mailto:${l.email}`} className="btn-outline py-1.5">Email</a>}
              </div>
            </article>
          );
        })}
      </div>
      {!leads.length && <p className="rounded-lg bg-white p-8 text-center text-sm text-muted">No leads yet.</p>}
    </>
  );
}
